/*
The plain decimal digits of a scaled value that no `number` can hold. `Intl.NumberFormat` is not involved, so the output carries no grouping or localized separator, the same as the fallback for a value with more fraction digits than it accepts.
*/
const toUnrepresentableString = (number, base, exponent, localeOptions) => {
	const scale = BigInt(base) ** BigInt(exponent);
	const whole = number / scale;

	// The 3 significant digit default never bites here: it only ever rounds to at least as many digits as the value has integers, and this one has far more than 3.
	if (localeOptions === undefined) {
		return whole.toString();
	}

	// The fraction digit options take over from that default, so the integer part stays exact and the fraction is truncated.
	const minimumFractionDigits = localeOptions.minimumFractionDigits ?? 0;
	const maximumFractionDigits = Math.max(localeOptions.maximumFractionDigits ?? 3, minimumFractionDigits);
	const truncated = ((number % scale) * (10n ** BigInt(maximumFractionDigits)) / scale).toString().padStart(maximumFractionDigits, '0');
	const fraction = truncated.replace(/0+$/, '').padEnd(minimumFractionDigits, '0');

	return fraction ? `${whole}.${fraction}` : whole.toString();
};

input.new_string:
/*
The plain decimal digits of a scaled value that no `number` can hold. `Intl.NumberFormat` is not involved, so the output carries no grouping or localized separator, the same as the fallback for a value with more fraction digits than it accepts.

`magnitudeMode` is one of `trunc`, `expand` and `halfExpand`, applied to the (non-negative) magnitude with exact `bigint` arithmetic.
*/
const toUnrepresentableString = (number, base, exponent, localeOptions, magnitudeMode = 'trunc') => {
	const scale = BigInt(base) ** BigInt(exponent);

	// The 3 significant digit default only ever rounds to at least as many digits as the value has integers, and this one has far more than 3, so it rounds to a whole number. The fraction digit options take over from that default.
	const minimumFractionDigits = localeOptions?.minimumFractionDigits ?? 0;
	const maximumFractionDigits = localeOptions === undefined ? 0 : Math.max(localeOptions.maximumFractionDigits ?? 3, minimumFractionDigits);
	const multiplier = 10n ** BigInt(maximumFractionDigits);
	const numerator = number * multiplier;
	let digits = numerator / scale;
	const remainder = numerator % scale;

	if ((magnitudeMode === 'expand' && remainder > 0n) || (magnitudeMode === 'halfExpand' && remainder * 2n >= scale)) {
		digits += 1n;
	}

	const whole = digits / multiplier;
	if (maximumFractionDigits === 0) {
		return whole.toString();
	}

	const fraction = (digits % multiplier).toString().padStart(maximumFractionDigits, '0').replace(/0+$/, '').padEnd(minimumFractionDigits, '0');

	return fraction ? `${whole}.${fraction}` : whole.toString();
};

const ROUNDING_MODES = new Set(['round', 'floor', 'ceil']);

const assertRoundingMode = roundingMode => {
	if (roundingMode !== undefined && !ROUNDING_MODES.has(roundingMode)) {
		throw new TypeError(`Expected roundingMode to be one of 'round', 'floor' or 'ceil', got ${typeof roundingMode}: ${String(roundingMode)}`);
	}
};

/*
The digits are rounded on the magnitude, after the sign has been split off, so `floor` and `ceil` swap for a negative value: `floor` moves toward negative infinity, which is away from zero for a negative value.
`undefined` keeps the behavior from before the option existed.
*/
const toMagnitudeMode = (roundingMode, isNegative) => {
	switch (roundingMode) {
		case 'round': {
			return 'halfExpand';
		}

		case 'floor': {
			return isNegative ? 'expand' : 'trunc';
		}

		case 'ceil': {
			return isNegative ? 'trunc' : 'expand';
		}

		default: {
			return undefined;
		}
	}
};

// `Intl.NumberFormat` caps significant digits at 21. A value with more integer digits than that is at least `1e21`, where every `number` is already a whole number, so there is nothing left to round.
const roundToSignificantDigits = (number, digits, magnitudeMode) => {
	if (digits > 21) {
		return number;
	}

	return Number(number.toLocaleString('en-US', {maximumSignificantDigits: digits, roundingMode: magnitudeMode, useGrouping: false}));
};

